import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[1].name, 'Logo package');
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice returns DATE_INVALID for bad format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10-07-2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns DATE_INVALID for impossible dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns NO_LINES for empty lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice returns NO_LINES for null lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: null,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -1 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns QTY_INVALID for fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns UNKNOWN_SKU for bad SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NOPE', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input lines', () => {
  const input = [{ sku: 'DES-HOUR', qty: 2 }];
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: input,
  });
  assert.deepEqual(input, [{ sku: 'DES-HOUR', qty: 2 }]);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 2,
    unitPrice: 8500,
    vatRate: 21,
  });
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 2, unitPrice: 8500 }), 17000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('invoiceTotals calculates subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 17000,
    total: 17000,
  });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 3 * 9500);
  assert.equal(totals.total, totals.subtotal);
});

test('addLine adds a new line to the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].qty, 3);
});

test('addLine increments qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
});

test('addLine returns QTY_INVALID for invalid quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine returns UNKNOWN_SKU for bad SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'NOPE', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  invoice.status = 'sent';
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const original = JSON.parse(JSON.stringify(invoice));
  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.deepEqual(invoice, original);
});

test('removeLine removes a line from the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const r = removeLine(invoice, 'DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine returns LINE_NOT_FOUND for missing SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  assert.deepEqual(removeLine(invoice, 'NOPE'), {
