    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine returns NO_LINES for last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
