  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('invoiceTotals calculates subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 17000,
    discount: 0,
    total: 17000,
  });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 3 * 9500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal);
});

