test('invoiceTotals calculates discount correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 50 }],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.total, 8500);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 2, discountPercent: 20 },
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 2 * 9500);
  assert.equal(totals.discount, (2 * 8500) * 0.1 + (2 * 9500) * 0.2);
  assert.equal(totals.total, totals.subtotal - totals.discount);
});

test('invoiceTotals clamps total to zero if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
